using System.Web;

public class AuditHelper
{
    // ASP.NET Framework: HttpContext.Current is a static ambient.
    // Calling this from a background thread or async continuation
    // already returned null in Framework; in .NET 10 it does not exist.
    public static string GetCurrentUserId()
    {
        var ctx = HttpContext.Current;
        if (ctx == null) return "anonymous";
        return ctx.User?.Identity?.Name ?? "anonymous";
    }

    // Also common: reading the raw URL from the ambient context.
    public static string GetRequestPath()
    {
        return HttpContext.Current?.Request?.RawUrl ?? "/";
    }
}
